class LibraryMember {protected String id;protected int limit,borrowed;private int[] fines=new int[10];private int fineCount;public LibraryMember(String id,int l){if(id==null||id.trim().length()<4||l<=0)throw new IllegalArgumentException();this.id=id;limit=l;}public LibraryMember(int l){this("LIBR",l);}public void borrowBook(){if(borrowed<limit)borrowed++;}public int getBooksBorrowed(){return borrowed;}public String displayInfo(){return "General Member | Books Borrowed: "+borrowed;}protected void chargeFine(int n){if(fineCount<10)fines[fineCount++]=n;}public int[] getFineHistory(){return java.util.Arrays.copyOf(fines,fineCount);}public int getTotalFine(){return java.util.Arrays.stream(fines,0,fineCount).sum();}}
class StudentMember extends LibraryMember {protected String course;public StudentMember(String i,int l,String c){super(i,l);course=c;}@Override public String displayInfo(){return "Student Member | Course: "+course+" | Books Borrowed: "+borrowed;}@Override protected void chargeFine(int n){super.chargeFine(n/2);}}
class HonorsStudentMember extends StudentMember {int bonus;public HonorsStudentMember(String i,int l,String c,int b){super(i,l,c);bonus=b;}@Override public String displayInfo(){return "Honors Student Member | Course: "+course+" | Bonus Limit: "+bonus+" | Books Borrowed: "+borrowed;}}
class FacultyMember extends LibraryMember {String department;public FacultyMember(String i,int l,String d){super(i,l);department=d;}public FacultyMember(int l,String d){super(l);department=d;}@Override public String displayInfo(){return "Faculty Member | Department: "+department+" | Books Borrowed: "+borrowed;}}
public class Problem2_MembershipTree {static String classifyGeneration(LibraryMember m){if(m instanceof HonorsStudentMember)return "Multilevel descendant (3 generations deep)";if(m instanceof FacultyMember)return "Hierarchical sibling (independent branch)";return "Base/student generation";}static int getTotalBooksBorrowed(LibraryMember[] ms){int n=0;for(LibraryMember m:ms)n+=m.getBooksBorrowed();return n;}static String batchPrint(LibraryMember[] ms){StringBuilder b=new StringBuilder();for(LibraryMember m:ms){if(b.length()>0)b.append(" | ");b.append(m.displayInfo());if(m instanceof StudentMember)b.append(" [Course via downcast: ").append(((StudentMember)m).course).append("]");}return b.toString();}static boolean isValidRenewalCode(String s){return s!=null&&s.length()==4&&s.charAt(0)=='R'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}static String processNightlyAudit(LibraryMember[] a){int p=0,n=0,f=0,r=0;for(LibraryMember m:a){if(m==null){n++;continue;}p++;if(m instanceof FacultyMember)f++;else r++;}return p+" processed | "+n+" null skipped | "+f+" faculty | "+r+" regular";}public static void main(String[]x){System.out.println(classifyGeneration(new HonorsStudentMember("STU3",3,"ECE",2)));}}